<?php
require __DIR__.'/config.php';date_default_timezone_set('Asia/Kolkata');auth();$pdo=db();$p=$_POST;$a=$p['action']??'';
$me=$pdo->prepare("SELECT username,COALESCE(role,'operator') role FROM users WHERE username=? LIMIT 1");$me->execute([$_SESSION['username']??'']);$me=$me->fetch()?:['username'=>'','role'=>'operator'];$admin=$me['role']==='admin'||strtolower($me['username'])==='admin';$op=$me['username'];
function bad($m){http_response_code(400);echo '<h3>Billing Error</h3><pre>'.htmlspecialchars($m,ENT_QUOTES,'UTF-8').'</pre><p><a href="billing.php">Back</a></p>';exit;}
if(!in_array($a,['create','update'],true))bad('Invalid action.');
$name=trim($p['customer_name']??'');if($name==='')bad('Customer name required.');$cats=$p['category']??[];$names=$p['item_name']??[];$models=$p['model']??[];$serial=$p['serial_no']??[];$qty=$p['qty']??[];$rates=$p['rate']??[];$items=[];$sub=0;
for($i=0;$i<count($names);$i++){ $n=trim($names[$i]??'');$q=(float)($qty[$i]??0);$r=(float)($rates[$i]??0);if($n===''||$q<=0)continue;$amt=round($q*$r,2);$sub+=$amt;$items[]=[trim($cats[$i]??''),$n,trim($models[$i]??''),trim($serial[$i]??''),$q,$r,$amt];}if(!$items)bad('At least one item is required.');
$discount=max(0,(float)($p['discount']??0));$gstRate=max(0,(float)($p['gst_rate']??0));$gst=round(max(0,$sub-$discount)*$gstRate/100,2);$grand=round(max(0,$sub-$discount)+$gst,2);$paid=min($grand,max(0,(float)($p['paid']??0)));$due=round($grand-$paid,2);$mode=trim($p['payment_mode']??'Cash');
try{$pdo->beginTransaction();if($a==='create'){$q=$pdo->prepare("INSERT INTO bills(bill_date,customer_name,mobile,address,gstin,subtotal,discount,gst_rate,gst_amount,grand_total,paid,due,payment_mode,remarks,operator_name) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$p['bill_date']??date('Y-m-d'),$name,trim($p['mobile']??''),trim($p['address']??''),trim($p['gstin']??''),$sub,$discount,$gstRate,$gst,$grand,$paid,$due,$mode,trim($p['remarks']??''),$op]);$id=(int)$pdo->lastInsertId();}else{$id=(int)($p['id']??0);$q=$admin?$pdo->prepare('SELECT id FROM bills WHERE id=?'):$pdo->prepare('SELECT id FROM bills WHERE id=? AND operator_name=?');$admin?$q->execute([$id]):$q->execute([$id,$op]);if(!$q->fetchColumn())throw new Exception('Bill not found or access denied.');$q=$pdo->prepare("UPDATE bills SET bill_date=?,customer_name=?,mobile=?,address=?,gstin=?,subtotal=?,discount=?,gst_rate=?,gst_amount=?,grand_total=?,paid=?,due=?,payment_mode=?,remarks=? WHERE id=?");$q->execute([$p['bill_date']??date('Y-m-d'),$name,trim($p['mobile']??''),trim($p['address']??''),trim($p['gstin']??''),$sub,$discount,$gstRate,$gst,$grand,$paid,$due,$mode,trim($p['remarks']??''),$id]);$pdo->prepare('DELETE FROM bill_items WHERE bill_id=?')->execute([$id]);}$q=$pdo->prepare('INSERT INTO bill_items(bill_id,category,item_name,model,serial_no,qty,rate,amount) VALUES(?,?,?,?,?,?,?,?)');foreach($items as $it)$q->execute([$id,...$it]);$pdo->commit();header('Location: invoice.php?id='.$id);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();bad($e->getMessage());}
